const body = $input.item.json.body;
const event = body.event;
const meta  = body.pool_metadata || {};
const match = body.match || {};
const pool  = body.pool  || {};

let text = '';

switch (event) {
  case 'match.goal':
    text = `⚽ *Gol!* ${match.home_team} ${match.home_score} x ${match.away_score} ${match.away_team}\n${meta.pool_name || pool.name || 'Bolão'}`;
    break;
  case 'match.live':
    text = `🏁 *Jogo começou!*\n${match.home_team} x ${match.away_team}\n${meta.pool_name || pool.name || 'Bolão'}`;
    break;
  case 'match.finished':
    text = `🔔 *Jogo encerrado!*\n${match.home_team} *${match.home_score}* x *${match.away_score}* ${match.away_team}\n${meta.pool_name || pool.name || 'Bolão'}`;
    break;
  case 'pool.ranking_updated':
    text = `📊 *Ranking atualizado!*\nLíder: ${body.leader || '—'}\n${meta.pool_name || pool.name || 'Bolão'}`;
    break;
  case 'pool.finished':
    text = `🏆 *Bolão encerrado!*\n${pool.name || meta.pool_name || 'Bolão'}\nConfira o resultado final!`;
    break;
  case 'tip.scored':
    text = `✅ *Palpite pontuado!*\n${(body.tip || {}).user || '—'} ganhou ${(body.tip || {}).points_earned || 0} pts\n${meta.pool_name || pool.name || 'Bolão'}`;
    break;
  case 'pool.daily_matches':
    const matches = (body.matches || []).map(m => `• ${m.home_team} x ${m.away_team} — ${m.scheduled_at}`).join('\n');
    text = `📅 *Jogos de hoje — ${pool.name || meta.pool_name || 'Bolão'}*\n${matches || 'Nenhum jogo hoje.'}`;
    break;
  default:
    text = `📣 Evento: *${event}*\n${meta.pool_name || pool.name || 'Bolão'}`;
}

return { ...body, _whatsapp_message: text, _group_id: meta.whatsapp_group_id };
